mapper.update:
UPDATE community_comments
SET content = #{content},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{commentId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM community_comments
WHERE id = #{commentId}
  AND user_id = #{userId}

mapper.select:
SELECT 
FROM community_comments
WHERE

    free_post_id = #{postId}
    question_post_id = #{postId}
    dispute_post_id = #{postId}
    FALSE

ORDER BY created_at ASC, id ASC
